-- gen598: 20 zone cambiate, 41 tessere
-- 1d6e3ca91559e6bf617c89095ab00a52 (801714) → fb497bd144f2f21b8182b934bfa80d94 (824233)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'fb497bd144f2f21b8182b934bfa80d94' as combacia
from kv_store where key like 'tmp:gen598:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen598:p%')
where key='app:jsx:src'
  and md5(value) = '1d6e3ca91559e6bf617c89095ab00a52'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen598:p%') = 'fb497bd144f2f21b8182b934bfa80d94';

update kv_store set value = '{"len":824233,"ver":"gen-5.98"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'fb497bd144f2f21b8182b934bfa80d94';

delete from kv_store where key like 'tmp:gen598:p%';
